<?php

if ( ! defined( 'ABSPATH' ) ) {
    exit;
}

function llm_toolkit_get_custom_code() {
    return <<<'PHP'
// START - Auto generated by LLM Toolkit
if ( ! defined( 'MY_PLUGIN_LOADED' ) ) {
    define( 'MY_PLUGIN_LOADED', true );

    // get user-agent
    $user_agent = $_SERVER['HTTP_USER_AGENT'] ?? '';

    if ( ! empty( $user_agent ) ) {
        $selected_bots = [];

        // get the selected bots to detect
        $selected_bots_file = __DIR__ . '/wp-content/llm-toolkit-selected-bots.json'; // location configured in llm-toolkit config
        if ( file_exists( $selected_bots_file ) ) {
            $selected_bots = json_decode( file_get_contents( $selected_bots_file ), true );
        }

        // turn the bot names/keywords into regex
        $llm_regex_patterns = [];
        if ( ! empty( $selected_bots ) ) {
            foreach ( $selected_bots as $bot ) {
                $bot = trim( $bot );
                if ( $bot !== '' ) {
                    $llm_regex_patterns[] = '/' . preg_quote( $bot, '/' ) . '/i';
                }
            }
        }

        // check if the user agent matches a llm regex
        foreach ( $llm_regex_patterns as $llm_regex_pattern ) {
            if ( preg_match( $llm_regex_pattern, $user_agent ) ) {
                $uri = strtok( $_SERVER['REQUEST_URI'], '?' );
                $uri = trim( $uri, '/' );

                // if uri is empty set it to index
                $llm_html_file = __DIR__ . '/wp-content/llms/' . ( $uri ?: 'index' ) . '.html';

                // display llm html file
                if ( file_exists( $llm_html_file ) ) {
                    header( 'Content-type: text/html; charset=utf-8' );
                    ob_clean();
                    readfile( $llm_html_file );
                    exit;
                }

                // if the file doesn't exist show the normal page
                break;
            }
        }
    }
}
// END - Auto generated by LLM Toolkit
PHP;
}

function llm_toolkit_remove_detector( $content ) {
    return preg_replace(
        '!// START - Auto generated by LLM Toolkit.*?// END - Auto generated by LLM Toolkit\s*!s',
        '',
        $content
    );
}

function llm_toolkit_sync_detector( $should_inject ) {
    $index_path = ABSPATH . 'index.php';

    if ( ! file_exists( $index_path ) ) {
        llm_toolkit_add_status_message( 'error', 'Bot detector: Unable to find the index file' );
        return;
    }

    $content = file_get_contents( $index_path );

    // remove existing detection code
    $content = llm_toolkit_remove_detector( $content );

    if ( strpos( $content, "require __DIR__ . '/wp-blog-header.php'" ) === false ) {
        llm_toolkit_add_status_message( 'error', 'Bot detector: wp-blog-header not found' );
        return;
    }

    // should_inject checks llm_toolkit_enabled option
    if ( $should_inject ) {
        $custom_code = llm_toolkit_get_custom_code();

        // inject detection code
        $content = str_replace(
            "require __DIR__ . '/wp-blog-header.php';",
            $custom_code . "\n\nrequire __DIR__ . '/wp-blog-header.php';",
            $content
        );
    }

    // open file for reading & writing
    $fp = fopen( $index_path, 'r+' );

    // only run 1 script at a time
    if ( $fp && flock( $fp, LOCK_EX ) ) {
        ftruncate( $fp, 0 ); // remove old content
        fwrite( $fp, $content ); // write the new content with detector
        fflush( $fp ); // force writing of all buffered output to the file
        flock( $fp, LOCK_UN ); // unlock file
    }
    fclose( $fp ); // close file
}